"use client";

import * as React from "react";
import { ArrowDown, ArrowUp } from "lucide-react";
import { cn } from "@/lib/utils";

/**
 * Metric — a stat / KPI display: label, value, an optional trend indicator
 * and an optional chart or icon slot (bring your own chart, e.g. compose
 * with `ChartContainer`).
 */
export interface MetricProps extends React.HTMLAttributes<HTMLDivElement> {
  label: React.ReactNode;
  value: React.ReactNode;
  trend?: "up" | "down" | "neutral";
  change?: React.ReactNode;
  icon?: React.ReactNode;
  chart?: React.ReactNode;
}

const Metric = React.forwardRef<HTMLDivElement, MetricProps>(
  ({ className, label, value, trend, change, icon, chart, ...props }, ref) => (
    <div ref={ref} className={cn("flex flex-col gap-2 rounded-md border border-input p-4 font-sans", className)} {...props}>
      <div className="flex items-center justify-between">
        <p className="text-body-sm text-muted-foreground">{label}</p>
        {icon && <span className="text-muted-foreground [&_svg]:size-5">{icon}</span>}
      </div>
      {/*
        Wraps rather than compresses. `justify-between` with two intrinsically-sized children has no
        give: once the value and the trend together need more than the card's content box, flex has
        nothing left to take and the pair is painted outside it — measured at 14px past the box on a
        149px card ("0.42%" / "0.1%"). Neither child can absorb the loss (a numeral must not be
        truncated, and splitting an arrow from its figure makes the trend unreadable), so the row
        gives way instead and the trend drops onto its own line under the value.

        `gap-x-3` rather than `gap-2`: 8px was the floor the compressed row was pinned at, which is
        exactly how close the two read before they collided. 12px is the spacing the rest of the
        system uses between related-but-distinct controls.

        `data-kx-metric-pair` is the handle the rendered gate measures this row by
        (scripts/web-quality-browser.mjs, the `spacing` check). It is a marker, never a styling hook.
      */}
      <div data-kx-metric-pair className="flex flex-wrap items-end justify-between gap-x-3 gap-y-1">
        <p className="min-w-0 break-words text-headline-sm font-medium text-foreground">{value}</p>
        {trend && (
          <span
            className={cn(
              // Three rules, in the order flex applies them, so the trend degrades one step at a time
              // instead of being clipped:
              //   `whitespace-nowrap`  the figure is never broken mid-number
              //   the row's `flex-wrap`  places items by their natural size BEFORE shrinking any, so a
              //                         trend too wide to sit beside the value reaches its own line whole
              //   `min-w-0` + `flex-wrap` here  the last resort, once the trend is alone on a line and
              //                         that line is still narrower than it (a 158px card at 200% text
              //                         leaves 92px for a 94px trend): the figure goes under the arrow.
              // Deliberately no `shrink-0`: it would hold the trend at its natural width and put the
              // overflow back, which is the defect this replaced.
              "inline-flex min-w-0 flex-wrap items-center gap-0.5 whitespace-nowrap text-label-md font-medium",
              trend === "up" && "text-success",
              trend === "down" && "text-destructive",
              trend === "neutral" && "text-muted-foreground",
            )}
          >
            {trend === "up" && <ArrowUp className="size-3.5" />}
            {trend === "down" && <ArrowDown className="size-3.5" />}
            {change}
          </span>
        )}
      </div>
      {chart && <div className="mt-1">{chart}</div>}
    </div>
  ),
);
Metric.displayName = "Metric";

export { Metric };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened — proven by the trigger having left the document, so a handler
 * that decides not to remove anything leaves focus exactly where the user put it.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
